MILLION_A_SHA3_256 = "5c8875ae474a3634ba4fd55ec85bffd661f32aca75c6d699d0cdcb6c115891c1"


class Sha3Tests(unittest.TestCase):
    def test_sha3_256_nist(self):
        for msg, expected in SHA3_256_NIST.items():
            self.assertEqual(sha3.sha3_256(msg).hex(), expected, msg)

    def test_sha3_512_nist(self):
        for msg, expected in SHA3_512_NIST.items():
            self.assertEqual(sha3.sha3_512(msg).hex(), expected, msg)

    def test_known_empty_digest(self):
        self.assertEqual(sha3.sha3_256(b"").hex(),
                         "a7ffc6f8bf1ed76651c14756a061d662f580ff4de43b49fa82d80a4b80f8434a")

    def test_block_boundaries(self):
        for n, expected in SHA3_256_LEN.items():
            self.assertEqual(sha3.sha3_256(pattern(n)).hex(), expected, n)
        for n, expected in SHA3_512_LEN.items():
            self.assertEqual(sha3.sha3_512(pattern(n)).hex(), expected, n)

    def test_incremental_update(self):
        data = pattern(500)
        h = sha3.Sha3_256()
        for i in range(0, len(data), 37):
            h.update(data[i:i + 37])
        self.assertEqual(h.digest(), sha3.sha3_256(data))
        self.assertEqual(h.digest(), sha3.sha3_256(data))  # digest tekrar çağrılabilir

    def test_million_a(self):
        self.assertEqual(sha3.sha3_256(b"a" * 1000000).hex(), MILLION_A_SHA3_256)


class ShakeTests(unittest.TestCase):
    def test_shake128_nist(self):
        for msg, expected in SHAKE128_NIST_32.items():
            self.assertEqual(sha3.shake128(msg, 32).hex(), expected, msg)

    def test_shake256_nist(self):
        for msg, expected in SHAKE256_NIST_64.items():
            self.assertEqual(sha3.shake256(msg, 64).hex(), expected, msg)

    def test_block_boundaries(self):
        for n, expected in SHAKE128_LEN_200.items():
            self.assertEqual(sha3.shake128(pattern(n), 200).hex(), expected, n)
        for n, expected in SHAKE256_LEN_200.items():
            self.assertEqual(sha3.shake256(pattern(n), 200).hex(), expected, n)

    def test_incremental_squeeze(self):
        # Kyber, SHAKE128'den parça parça çıktı okur; sonuç tek seferlik okumayla aynı olmalı
        one_shot = sha3.shake128(b"tohum", 700)
        xof = sha3.Shake128(b"tohum")
        pieces = xof.squeeze(1) + xof.squeeze(167) + xof.squeeze(168) + xof.squeeze(364)
        self.assertEqual(pieces, one_shot)

    def test_update_after_squeeze_fails(self):
        xof = sha3.Shake256(b"a")
        xof.squeeze(8)
        with self.assertRaises(ValueError):
            xof.update(b"b")


class KeccakTests(unittest.TestCase):
    def test_round_constants(self):
        self.assertEqual(len(sha3.RC), 24)
        self.assertEqual(sha3.RC[0], 0x0000000000000001)
        self.assertEqual(sha3.RC[1], 0x0000000000008082)
        self.assertEqual(sha3.RC[23], 0x8000000080008008)

    def test_rotation_offsets(self):
        self.assertEqual(sha3.ROT[0][0], 0)
        self.assertEqual(sha3.ROT[1][0], 1)
        self.assertEqual(sha3.ROT[0][2], 3)
        self.assertEqual(sha3.ROT[4][4], 14)

    def test_permutation_of_zero_state(self):
        # Sıfır durumuna bir kez Keccak-f[1600] uygulanınca ilk şerit bilinen değerdir
        state = [0] * 25
        sha3.keccak_f1600(state)
        self.assertEqual(state[0], 0xF1258F7940E1DDE7)


if __name__ == "__main__":
    unittest.main()
